using System;using System.Collections;using System.Collections.Generic;using System.Linq;using UnityEngine;using UnityEngine.UI;using HeartOfTheRain.M46;using HeartOfTheRain.M47;
namespace HeartOfTheRain.App.FirstStart {
 public sealed class PracticeBoardView:MonoBehaviour {
  FirstStartAssets assets;FirstStartSession session;Action<string> changed;RawImage target;M46AtlasBank bank;BoardPresentation presentation;Transform world;Camera cameraView;RenderTexture texture;Material bodyMaterial;GameplayFeedback feedback;
  readonly List<SpriteRenderer> pool=new List<SpriteRenderer>();readonly MaterialPropertyBlock light=new MaterialPropertyBlock();List<BoardStep> queue;int cursor;BoardStep current;BoardSnapshot idle;float clock,started;bool preparing,suspended,reducedMotion;const int Layer=31;
  public bool Preparing=>preparing;public bool Suspended{get{return suspended;}set{suspended=value;if(feedback)feedback.Pause(value);}}
  public void Configure(FirstStartAssets a,FirstStartSession s,Action<string> onChanged,bool sound,bool reduceMotion){Release();assets=a;session=s;changed=onChanged;reducedMotion=reduceMotion;bank=new M46AtlasBank(a.Gameplay.boards);presentation=new BoardPresentation{columns=5,rows=5,left=-.9f,right=4.9f,bottom=-.9f};foreach(var p in a.Gameplay.boards.debrisProfiles){var profile=JsonUtility.FromJson<DebrisProfile>(p.metadata.text);foreach(var piece in profile.pieces){if(piece.scaleMultiplier<=0)piece.scaleMultiplier=1;if(piece.spinMultiplier<=0)piece.spinMultiplier=1;}presentation.profiles[p.family]=profile;}
   world=new GameObject("First Start practice stage").transform;world.SetParent(transform,false);world.localPosition=new Vector3(10000,0,0);
   var cameraObject=new GameObject("Practice render camera");cameraObject.transform.SetParent(world,false);cameraView=cameraObject.AddComponent<Camera>();cameraView.orthographic=true;cameraView.orthographicSize=2.9f;cameraView.aspect=1;cameraView.cullingMask=1<<Layer;cameraView.clearFlags=CameraClearFlags.SolidColor;cameraView.backgroundColor=new Color(.10f,.18f,.24f,0);cameraView.transform.localPosition=new Vector3(2,2,-10);cameraView.nearClipPlane=.1f;cameraView.farClipPlane=20;cameraView.allowHDR=false;
   texture=new RenderTexture(768,768,16,RenderTextureFormat.ARGB32);texture.name="First Start practice";texture.Create();cameraView.targetTexture=texture;
   bodyMaterial=new Material(a.Gameplay.bodyShader?a.Gameplay.bodyShader:Shader.Find("Sprites/Default"));
   for(int y=0;y<5;y++)for(int x=0;x<5;x++){var sr=Make("Practice cell",0);sr.sprite=a.Find((x+y)%2==0?"FS_CellLight":"FS_CellSlate");sr.sharedMaterial=bodyMaterial;sr.transform.localPosition=new Vector3(x,y,0);sr.transform.localScale=Vector3.one/sr.sprite.bounds.size.x;}
   var maskObject=new GameObject("Practice body mask");maskObject.layer=Layer;maskObject.transform.SetParent(world,false);maskObject.transform.localPosition=new Vector3(2,2,0);var mask=maskObject.AddComponent<SpriteMask>();mask.sprite=a.Find("FS_CellLight");maskObject.transform.localScale=Vector3.one*(5/mask.sprite.bounds.size.x);mask.isCustomRangeActive=true;mask.frontSortingOrder=15;mask.backSortingOrder=5;
   feedback=world.gameObject.AddComponent<GameplayFeedback>();feedback.assets=a.Gameplay;feedback.SetSoundEnabled(sound);idle=s.Board.Snapshot();clock=started=0;cursor=0;queue=null;current=null;preparing=false;Draw();Bind(target);
  }
  public void Bind(RawImage image){target=image;if(target)target.texture=texture;}
  SpriteRenderer Make(string name,int order){var go=new GameObject(name);go.layer=Layer;go.transform.SetParent(world,false);var sr=go.AddComponent<SpriteRenderer>();sr.sortingOrder=order;return sr;}
  public void Play(TurnResult result){if(!result.accepted||preparing||current!=null)return;queue=result.steps;cursor=0;preparing=true;changed?.Invoke("Loading effects…");StartCoroutine(Prepare());}
  IEnumerator Prepare(){yield return bank.Prewarm(bank.RequiredResources(queue));if(bank.LoadError!=null){changed?.Invoke("Could not load. Retry or skip.");yield break;}preparing=false;changed?.Invoke("");Next();}
  void Next(){if(cursor>=queue.Count){current=null;idle=session.Board.Snapshot();session.FinishAnimation();changed?.Invoke("");return;}current=queue[cursor++];started=clock;presentation.Add(current,started);feedback.Begin(current);feedback.Sample(0);}
  void Update(){if(bank==null||suspended)return;clock+=Time.unscaledDeltaTime;if(current!=null){feedback.Sample(clock-started);if(clock-started>=current.duration)Next();}Draw();}
  void Draw(){if(bank==null||idle==null)return;bank.BeginFrame();presentation.PruneHistory(clock);var draws=presentation.Sample(current,idle,clock,started);int count=0;foreach(var d in draws){if(reducedMotion&&!d.masked)continue;var sprite=bank.Get(d);if(!sprite||d.alpha<=0)continue;if(count>=pool.Count)pool.Add(Make("Approved practice effect",d.order));var sr=pool[count++];sr.enabled=true;sr.sprite=sprite;sr.sortingOrder=d.order;sr.sharedMaterial=d.glow>0?assets.Gameplay.boards.tileGlowMaterial:d.masked?bodyMaterial:assets.Gameplay.boards.effectsMaterial;sr.maskInteraction=d.masked?SpriteMaskInteraction.VisibleInsideMask:SpriteMaskInteraction.None;sr.transform.localPosition=new Vector3(d.x,d.y,0);sr.transform.localScale=new Vector3(d.sx,d.sy,1);sr.transform.localRotation=Quaternion.Euler(0,0,d.angle);sr.color=new Color(d.red,d.green,d.blue,d.alpha);light.Clear();light.SetFloat("_Glow",d.glow);sr.SetPropertyBlock(light);}for(int i=count;i<pool.Count;i++){pool[i].enabled=false;pool[i].sprite=null;}bank.EndFrame(current==null&&!preparing);}
  public void Release(){StopAllCoroutines();preparing=false;if(cameraView)cameraView.targetTexture=null;if(target)target.texture=null;if(world){world.gameObject.SetActive(false);Destroy(world.gameObject);}world=null;cameraView=null;feedback=null;pool.Clear();if(texture){texture.Release();Destroy(texture);}texture=null;if(bodyMaterial)Destroy(bodyMaterial);bodyMaterial=null;if(bank!=null)bank.Dispose();bank=null;idle=null;current=null;queue=null;}
  void OnDestroy(){Release();}
 }
}
